// nethack_lookup: offline facts from the NetHack 5.0 source (monsters, objects, appearances, roles, races; data in
// nethack-5.0.json, generated by scripts/gen-nethack-data.ts) plus hand-written, source-cited effect tables for
// fountains, sinks, thrones and altars (effects.ts). Fuzzy name matching; unknown names get "not in NetHack 5.0".
// Spoiler-level lines (price/frequency of randomized items, quest and unique monsters, full effect tables) are
// returned under a SPOILER-LEVEL marker so the assistant can gate them on the player's consent.
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { EFFECT_ENTRIES } from "./effects.ts";

export type LookupKind = "monster" | "object" | "artifact" | "appearance" | "role" | "race" | "feature" | "mechanic";

export interface LookupEntry {
  kind: LookupKind;
  name: string;
  aliases: string[];
  heading: string;
  /** source file(s) the facts come from */
  source: string;
  lines: string[];
  /** spoiler-level lines (empty: nothing gated) */
  spoiler: string[];
}

export interface LookupData {
  source: string;
  entries: LookupEntry[];
}

const DATA_FILE = new URL("./nethack-5.0.json", import.meta.url);
let data: LookupEntry[] | null = null;

export function lookupEntries(): LookupEntry[] {
  if (!data) {
    const d = JSON.parse(readFileSync(DATA_FILE, "utf8")) as LookupData;
    data = [...d.entries, ...EFFECT_ENTRIES];
  }
  return data;
}

/** lower case, no articles / punctuation, simple singular */
export function normalize(s: string): string {
  let t = s
    .toLowerCase()
    .replace(/[’`]/g, "'")
    .replace(/[^a-z0-9' -]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^(?:a|an|the|some|my)\s+/, "");
  // plural of the head word ("jackals", "gnome lords", "potions of healing", "elves")
  const IRREGULAR: Record<string, string> = { knives: "knife", mice: "mouse", teeth: "tooth", djinn: "djinni", men: "man", women: "woman" };
  const sing = (w: string) =>
    IRREGULAR[w] ?? (w.length <= 3 || /(?:ss|us|is)$/.test(w) ? w
      : /ves$/.test(w) ? w.replace(/ves$/, "f")
        : /ies$/.test(w) ? w.replace(/ies$/, "y")
          : /(?:ch|sh|x)es$/.test(w) ? w.replace(/es$/, "")
            : w.replace(/s$/, ""));
  const of = t.indexOf(" of ");
  if (of > 0) t = sing(t.slice(0, of)) + t.slice(of);
  else {
    const ws = t.split(" ");
    ws[ws.length - 1] = sing(ws[ws.length - 1]);
    t = ws.join(" ");
  }
  return t;
}

/** Damerau-Levenshtein (optimal string alignment) distance */
export function editDistance(a: string, b: string): number {
  const d: number[][] = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
    }
  return d[a.length][b.length];
}

interface Match { entry: LookupEntry; key: string; score: number }

/** Best matches for a query: 0 = exact (after normalization); higher = worse. */
export function findMatches(query: string, kind?: LookupKind): Match[] {
  const q = normalize(query);
  const out: Match[] = [];
  for (const e of lookupEntries()) {
    if (kind && e.kind !== kind && !(kind === "object" && e.kind === "appearance")) continue;
    let best = Infinity;
    let bestKey = e.name;
    for (const key of [e.name, ...e.aliases]) {
      const k = normalize(key);
      let score: number;
      if (k === q) score = 0;
      else if (q.length >= 4 && (` ${k} `.includes(` ${q} `) || ` ${q} `.includes(` ${k} `))) score = 0.15 + Math.abs(k.length - q.length) / (4 * Math.max(k.length, q.length));
      else score = editDistance(q, k) / Math.max(q.length, k.length);
      if (score < best) {
        best = score;
        bestKey = key;
      }
    }
    out.push({ entry: e, key: bestKey, score: best });
  }
  // prefer monsters / objects over appearance entries on ties
  const rank = (m: Match) => m.score + (m.entry.kind === "appearance" ? 0.01 : 0);
  return out.sort((a, b) => rank(a) - rank(b));
}

function render(e: LookupEntry): string {
  const head = `NetHack 5.0 ${e.kind === "feature" ? "dungeon feature" : e.kind === "mechanic" ? "game mechanic" : e.kind} data (from ${e.source}): ${e.heading}`;
  const spoiler = e.spoiler.length
    ? `\nSPOILER-LEVEL (give only if the player asked for spoilers / agreed; otherwise give the general facts above and offer):\n${e.spoiler.join("\n")}`
    : "";
  return `${head}\n${e.lines.length ? e.lines.join("\n") : "(Everything about it is spoiler-level.)"}${spoiler}`;
}

/** Does the name occur anywhere in the 5.0 source (code, level files, Guidebook)? null: cannot tell. */
function inSource(srcDir: string, name: string): boolean | null {
  const r = spawnSync("rg", ["--ignore-case", "--fixed-strings", "--word-regexp", "--files-with-matches", "--max-count", "1", "-e", name, "src", "dat", "include", "doc/Guidebook.txt"], {
    cwd: srcDir,
    timeout: 3000,
    encoding: "utf8",
  });
  if (r.error || (r.status !== 0 && r.status !== 1)) return null;
  return r.status === 0;
}

/** The nethack_lookup tool. `srcDir`: the 5.0 source tree, to tell "unknown here" from "not in the game". */
export function nethackLookup(args: { name: string; kind?: string }, opts: { srcDir?: string } = {}): string {
  const name = String(args.name ?? "").trim();
  if (!name) return "Missing name.";
  const kind = (["monster", "object", "artifact", "appearance", "role", "race", "feature", "mechanic"] as const).find((k) => k === args.kind);
  const matches = findMatches(name, kind);
  const exact = matches.filter((m) => m.score === 0);
  if (exact.length) {
    // one name for several things (the Valkyrie role and the valkyrie player-monster): show all, most useful first
    const order: LookupKind[] = ["role", "race", "feature", "mechanic", "artifact", "monster", "object", "appearance"];
    exact.sort((a, b) => order.indexOf(a.entry.kind) - order.indexOf(b.entry.kind));
    return exact.slice(0, 3).map((m) => render(m.entry)).join("\n\n");
  }
  const best = matches[0];
  const near = matches.filter((m) => m.score <= 0.34).slice(0, 5);
  if (best && best.score <= 0.2 && (matches[1]?.score ?? 1) - best.score >= 0.05) {
    return `(No exact match for "${name}"; closest is "${best.key}".)\n${render(best.entry)}`;
  }
  const closest = (near.length ? near : matches.slice(0, 5)).map((m) => `${m.entry.name} (${m.entry.kind})`);
  const mentioned = opts.srcDir ? inSource(opts.srcDir, name) : null;
  if (mentioned)
    return `"${name}" is not a monster, object, artifact, role, race or dungeon feature in the lookup tables, but it does appear in the NetHack 5.0 source, so it is some other game concept: use fetch_wiki_page or search_nethack_source. Similar names in the tables: ${closest.join(", ")}.`;
  return `"${name}" is not in NetHack 5.0 (no ${kind ?? "monster, object, role, race or dungeon feature"} by that name in the 5.0 source). Closest names: ${closest.join(", ")}.${near.length ? " If one of these was meant, look it up by that name." : ""}`;
}
